    .story-card strong { display: block; color: var(--navy); }
    .story-card span { font-size: 0.88rem; color: var(--muted); }
    .about-text h2 { font-size: clamp(2rem, 4vw, 2.6rem); margin-bottom: 20px; }
    .about-text p { color: var(--muted); margin-bottom: 16px; }
    .about-text blockquote {
      margin: 26px 0;
      padding-left: 20px;
      border-left: 4px solid var(--copper);
      font-family: Georgia, serif;
      font-style: italic;
      font-size: 1.15rem;
