    .values {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 18px;
      margin: 28px 0 34px;
    }
    .value {
      display: flex;
      gap: 12px;
      align-items: flex-start;
    }
    .value svg { width: 22px; height: 22px; color: var(--teal); flex-shrink: 0; margin-top: 3px; }
    .value strong { display: block; color: var(--navy); font-size: 0.98rem; }
    .value span { font-size: 0.9rem; color: var(--muted); }

    /* Process */
    .process { background: var(--white); }
    .steps {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      position: relative;
      counter-reset: step;
    }
    .steps::before {
      content: "";
      position: absolute;
      top: 34px;
      left: 12%;
      right: 12%;
      height: 2px;
      background: repeating-linear-gradient(90deg, var(--border) 0 10px, transparent 10px 18px);
      z-index: 0;
