      font-size: 0.9rem;
      background: var(--teal);
      color: var(--white);
    }
    .review-author strong { display: block; font-size: 0.95rem; }
    .review-author span { font-size: 0.82rem; color: #9fb3c8; }

    /* Areas */
    .areas { background: var(--cream); }
