      display: grid;
      grid-template-columns: 0.8fr 1.2fr;
      gap: 70px;
      align-items: start;
    }
    .faq-wrap h2 { font-size: clamp(2rem, 4vw, 2.6rem); margin-bottom: 16px; }
    .faq-wrap > div > p { color: var(--muted); margin-bottom: 24px; }
    details {
      border-bottom: 1px solid var(--border);
      padding: 22px 0;
