    details:first-child { border-top: 1px solid var(--border); }
    summary {
      cursor: pointer;
      list-style: none;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      font-weight: 700;
      color: var(--navy);
      font-size: 1.05rem;
    }
    summary::-webkit-details-marker { display: none; }
    summary::after {
      content: "+";
      font-size: 1.6rem;
      line-height: 1;
      color: var(--copper);
      transition: transform 0.2s ease;
      flex-shrink: 0;
    }
    details[open] summary::after { transform: rotate(45deg); }
    details p {
      color: var(--muted);
      margin-top: 12px;
      font-size: 0.97rem;
    }

    /* Contact */
    .contact { background: var(--cream); }
    .contact-grid {
      display: grid;
      grid-template-columns: 1fr 1.1fr;
      gap: 60px;
      align-items: start;
    }
    .contact-info h2 { font-size: clamp(2rem, 4vw, 2.6rem); margin-bottom: 16px; }
    .contact-info > p { color: var(--muted); margin-bottom: 32px; }
    .contact-item {
      display: flex;
      gap: 16px;
      align-items: flex-start;
      margin-bottom: 24px;
    }
    .contact-item .icon-wrap { margin-bottom: 0; width: 50px; height: 50px; border-radius: 14px; }
    .contact-item .icon-wrap svg { width: 24px; height: 24px; }
    .contact-item strong { display: block; color: var(--navy); margin-bottom: 2px; }
    .contact-item a, .contact-item span { color: var(--muted); font-size: 0.97rem; }
    .contact-item a:hover { color: var(--teal); }
    .form-card {
      background: var(--white);
      border-radius: 20px;
      padding: 40px;
      box-shadow: var(--shadow);
    }
    .form-card h3 { font-size: 1.6rem; margin-bottom: 6px; }
    .form-card > p { color: var(--muted); font-size: 0.95rem; margin-bottom: 24px; }
    .form-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }
    .form-card .btn { width: 100%; margin-top: 8px; }

    /* Footer */
    footer {
      background: var(--navy-dark);
      color: #aebdcd;
      padding: 70px 0 30px;
      font-size: 0.95rem;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr 1fr 1fr 1fr;
      gap: 44px;
